package com.tihai.utils;
import org.springframework.stereotype.Service;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.context.ApplicationContext;import com.tihai.dubbo.pojo.course.Course;import okhttp3.*;import org.jsoup.*;import org.jsoup.nodes.*;import java.util.*;import java.util.regex.*;import java.io.*;
@Service public class CourseExamCatalog {
 @Autowired private com.tihai.utils.AccountRegistry registry;@Autowired JdbcTemplate db;@Autowired ApplicationContext context;
 public static class Entry {public String id,account,courseId,clazzId,cpi,examId,title,courseTitle,notesUrl,status,detail;public boolean actionable;}
 private final Map<String,Entry> entries=new java.util.concurrent.ConcurrentHashMap<>();private List<Map<String,Object>> cached;private long cachedAt;private String scopeKey="";
 public CourseUtil session(String account){String cookie=db.queryForObject("SELECT cookies FROM th_wk_user WHERE account=? LIMIT 1",String.class,account);CourseUtil u=new CourseUtil();context.getAutowireCapableBeanFactory().autowireBean(u);u.setAccount(account);u.setCookies(cookie);return u;}
 public String cookies(String account){return db.queryForObject("SELECT cookies FROM th_wk_user WHERE account=? LIMIT 1",String.class,account);}
 public static String get(OkHttpClient http,String target)throws IOException{HttpUrl u=HttpUrl.parse(target);if(u==null||!u.isHttps()||!u.host().endsWith(".chaoxing.com"))throw new IOException("考试地址不受支持");try(Response r=http.newCall(new Request.Builder().url(u).get().build()).execute()){if(!r.isSuccessful()||r.body()==null||r.request().url().host().contains("passport"))throw new IOException("考试会话过期或页面读取失败");return r.body().string();}}
 static String value(Document d,String id){Element e=d.getElementById(id);return e==null?"":e.val();}
 public Entry entry(String id)throws IOException{Entry e=entries.get(id);if(e==null)throw new IOException("考试入口已过期，请刷新列表");return e;}
 public synchronized void invalidate(){cachedAt=0;}
 public static List<Entry> parse(String html,String account,Course c)throws IOException{
  Document d=Jsoup.parse(html);if(!d.title().contains("考试"))throw new IOException("课程考试列表结构未识别");List<Entry> out=new ArrayList<>();
  for(Element li:d.select(".ulDiv > ul > li")){Element a=li.selectFirst(".titTxt p a[title]");if(a==null)continue;Matcher m=Pattern.compile("goTest\\(\\s*['\"]?(\\d+)['\"]?\\s*,\\s*(\\d+)\\s*,").matcher(a.attr("onclick"));if(!m.find()){continue;}if(!c.getCourseId().equals(m.group(1)))throw new IOException("考试所属课程不匹配");Entry e=new Entry();e.account=account;e.courseId=c.getCourseId();e.clazzId=c.getClazzId();e.cpi=c.getCpi();e.examId=m.group(2);e.title=a.attr("title");e.courseTitle=c.getTitle();e.status=li.select(".titTxt strong").text();if(e.status.isEmpty())e.status="考试安排";e.detail=li.select(".titTxt").text();e.actionable=Arrays.asList("待做","进行中","未完成","待考试").contains(e.status);e.id=UUID.nameUUIDFromBytes((account+"|exam|"+e.courseId+"|"+e.clazzId+"|"+e.examId).getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString();e.notesUrl=HttpUrl.parse("https://mooc1.chaoxing.com/exam-ans/exam/test/examcode/examnotes").newBuilder().addQueryParameter("courseId",e.courseId).addQueryParameter("classId",e.clazzId).addQueryParameter("examId",e.examId).addQueryParameter("cpi",e.cpi).build().toString();out.add(e);}
  if(out.isEmpty()&&!d.text().contains("暂无内容")&&!d.select(".ulDiv > ul > li").isEmpty())throw new IOException("考试条目结构尚未识别");return out;
 }
 public synchronized Map<String,Object> list(){List<String> errors=new ArrayList<>();if(!scopeKey.equals(AccountScope.cacheKey())){cached=null;scopeKey=AccountScope.cacheKey();}if(cached==null||System.currentTimeMillis()-cachedAt>60000){List<Map<String,Object>> rows=new ArrayList<>();for(Map<String,Object> row:com.tihai.utils.AccountScope.accounts(db)){String account=String.valueOf(row.get("login_account"));try{Set<String> selected=new HashSet<>(db.queryForList("SELECT DISTINCT course_id FROM th_wk_queue WHERE login_account=?",String.class,account));CourseUtil u=session(account);OkHttpClient http=u.initSession(false,false).newBuilder().callTimeout(35,java.util.concurrent.TimeUnit.SECONDS).build();for(Course c:u.getCourseList())if(selected.contains(c.getCourseId()))try{
    HttpUrl middle=HttpUrl.parse("https://mooc1.chaoxing.com/visit/stucoursemiddle").newBuilder().addQueryParameter("courseid",c.getCourseId()).addQueryParameter("clazzid",c.getClazzId()).addQueryParameter("cpi",c.getCpi()).addQueryParameter("ismooc2","1").addQueryParameter("v","2").build();Document md=Jsoup.parse(get(http,middle.toString()));String token=value(md,"examEnc");if(token.isEmpty())throw new IOException("考试入口签名未生成");HttpUrl list=HttpUrl.parse("https://mooc1.chaoxing.com/exam-ans/exam/test").newBuilder().addQueryParameter("courseId",c.getCourseId()).addQueryParameter("classId",c.getClazzId()).addQueryParameter("cpi",c.getCpi()).addQueryParameter("ut","s").addQueryParameter("enc",token).addQueryParameter("openc",value(md,"openc")).addQueryParameter("size","9").build();String first=get(http,list.toString());Matcher pages=Pattern.compile("Math\\.ceil\\((\\d+)/9\\)").matcher(first);int total=pages.find()?Integer.parseInt(pages.group(1)):9;if(total>500)throw new IOException("考试数量超出本次读取范围");
    for(int start=0;start<Math.max(1,total);start+=9){String html=start==0?first:get(http,list.newBuilder().setQueryParameter("start",String.valueOf(start)).build().toString());for(Entry e:parse(html,account,c)){entries.put(e.id,e);if(registry!=null)registry.resource("exam",e.id,e.account);Map<String,Object> item=new LinkedHashMap<>();item.put("id",e.id);item.put("title",e.title);item.put("course",e.courseTitle);item.put("status",e.status);item.put("detail",e.courseTitle+" · "+e.detail);item.put("actionable",e.actionable);rows.add(item);}}
   }catch(Exception ex){errors.add("部分课程考试未完整读取，请核对账号、课程权限或稍后刷新");}}
   catch(Exception ex){errors.add("考试账号会话不可用，请重新查询课程登录");}}
   cached=rows;cachedAt=errors.isEmpty()?System.currentTimeMillis():0;}
  Map<String,Object> data=new LinkedHashMap<>();data.put("items",cached);data.put("errors",errors);data.put("message","已添加课程的考试 · "+cached.size()+" 项 · 平台安全验证需人工完成");return data;
 }
}
